parameters.jsCode:
// ---------------------------------------------------------------------
// WF-15: normalize an approval request.
// All irreversible actions (publish, bulk send, delete, settings change,
// spend, infra change) MUST land here before execution.
// ---------------------------------------------------------------------
const j = $input.first().json;

const allowedActions = ['publish', 'send', 'bulk_send', 'delete', 'change_settings', 'other'];
const action = String(j.action || 'other').toLowerCase();
if (!allowedActions.includes(action)) {
  throw new Error('APPROVAL_DENIED: unknown action ' + action);
}

return [{
  json: {
    entity_type: j.entity_type || 'unknown',
    entity_id: j.entity_id || null,
    action,
    payload_json: j.payload || {},
    status: 'HUMAN_REVIEW',
    requested_by: j.requested_by || 'master_agent',
    created_at: new Date().toISOString(),
  },
}];

parameters.responseBody:
={
  "queued": true,
  "status": "HUMAN_REVIEW",
  "action": $json.action,
  "note": "Approval is pending human review. Publishing/sending stays blocked until APPROVED."
}
